const $=s=>document.querySelector(s),main=$('main');let progress;try{progress=JSON.parse(localStorage.getItem('bio-progress')||'{}')}catch{progress={}}progress.done||=[];progress.known||=[];progress.missed||=[];let deck=[],ci=0,flipped=false,quiz=[],qi=0,answers=[],checked=false,mode='study';const save=()=>{try{localStorage.setItem('bio-progress',JSON.stringify(progress))}catch{}};const shuffle=a=>a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v);const topic=id=>TOPICS.find(t=>t.id===id);const button=(text,fn,light=false)=>`<button class="btn ${light?'light':''}" onclick="${fn}">${text}</button>`;const options=(all=true)=>`${all?'<option value="all">All topics</option><option value="unit2">Unit 2 + enzymes</option>':''}${TOPICS.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}`;const matches=(t,f)=>f==='all'||f==='unit2'&&topic(t).group!=='Beyond Unit 2'||t===f;
function molecule(x=150,y=120){return `<g transform="translate(${x} ${y})"><path d="M-40 38L0 0L45 38" stroke="#92a484" stroke-width="13" fill="none"/><circle r="36" fill="#49775c"/><circle cx="-45" cy="42" r="22" fill="#cedf9f"/><circle cx="48" cy="42" r="22" fill="#cedf9f"/><text x="0" y="7" text-anchor="middle" fill="white" font-size="21">O</text><text x="-45" y="48" text-anchor="middle">H</text><text x="48" y="48" text-anchor="middle">H</text><text x="0" y="-47" text-anchor="middle">δ−</text><text x="-65" y="83">δ+</text><text x="50" y="83">δ+</text></g>`}
function heroArt(){return `<div class="art"><svg viewBox="0 0 500 330" role="img" aria-label="Water molecules with partial charges and an attraction between them"><circle cx="250" cy="165" r="128" fill="none" stroke="#cbd7b9" stroke-dasharray="4 8"/><path d="M222 145L287 185" stroke="#8fa659" stroke-width="3" stroke-dasharray="7 7"/>${molecule(155,100)}${molecule(345,195)}</svg><div class="art-label one">Small molecules.<br><strong>Big connections.</strong></div><div class="art-label two">✧ &nbsp; Learn by exploring</div></div>`}
function home(){main.innerHTML=`<section class="hero"><div><span class="eyebrow">LESS CONFUSION. MORE “OH, I GET IT.”</span><h1>Biology makes sense.<br><em>Let’s find your way in.</em></h1><p class="lead">Your notes, made clearer. Bite-sized lessons, hands-on models, and practice that helps the ideas click.</p><div class="actions"><a class="btn" href="#lesson/water">Start Unit 2 &nbsp; ↗</a><a class="btn light" href="#lab">Explore a model</a></div><span class="mini">No account needed · Go at your pace · Pick up where you left off</span></div>${heroArt()}</section><div class="status"><div><strong>${progress.done.length}<span> / ${TOPICS.length}</span></strong><br><span>sections explored</span></div><div class="bar"><i style="width:${progress.done.length/TOPICS.length*100}%"></i></div><span>Read → explore → try it yourself</span><a href="#practice" class="btn light">Quick practice ↗</a></div><div class="section-head"><div><span class="eyebrow">YOUR LEARNING PATH</span><h2>Start with the chemistry of life.</h2></div><span class="badge">UNIT 2 · FROM YOUR NOTES</span></div><p class="sub">Water, pH, molecules, and proteins—broken into pieces you can actually understand.</p><div class="grid">${TOPICS.filter(t=>t.group!=='Beyond Unit 2').map(tile).join('')}</div><div class="wide"><a class="feature dark" href="#lab"><span class="eyebrow" style="color:#d8ed9e">THE MODEL LAB</span><h3>Don’t just read it. Change it.</h3><p>Adjust pH, build a chain, or unfold a protein. See the cause and effect.</p><strong>Try the interactive models &nbsp; ↗</strong></a><a class="feature" href="#cards"><span class="eyebrow">MAKE IT STICK</span><h3>A little recall goes a long way.</h3><p>Flip through flashcards, flag what needs work, and come back stronger.</p><strong>Open your flashcards &nbsp; ↗</strong></a></div><div class="section-head"><div><span class="eyebrow">KEEP GOING</span><h2>Beyond Unit 2</h2></div></div><p class="sub">Subject-based study sections for what comes next. Your teacher’s sequence may differ; these are not assigned unit numbers.</p><div class="grid">${TOPICS.filter(t=>t.group==='Beyond Unit 2').map(tile).join('')}</div>`}
function tile(t){return `<a class="card" href="#lesson/${t.id}"><div class="icon">${t.icon}</div><span class="num">${t.group}${progress.done.includes(t.id)?' · ✓ EXPLORED':''}</span><h3>${t.title}</h3><p>${t.desc}</p><div class="card-bottom"><span>${t.parts.length} short explanations · model + practice</span><b>↗</b></div></a>`}
function lesson(id){let t=topic(id);if(!t){location.hash='home';return}main.innerHTML=`<div class="breadcrumb"><a href="#home">Your path</a> / ${t.group} / ${t.title}</div><div class="lesson-layout"><aside class="side" aria-label="Sections">${TOPICS.map(u=>`<a class="${u.id===id?'active':''}" href="#lesson/${u.id}">${u.icon} &nbsp; ${u.title}</a>`).join('')}</aside><article class="lesson"><span class="eyebrow">${t.group.toUpperCase()} · LEARN AT YOUR PACE</span><h1>${t.title}</h1><p>${t.desc}</p><div class="callout"><strong>The big idea</strong><p>${t.example}</p></div>${t.parts.map((p,i)=>`<section><h2 style="margin-top:35px;font-size:23px">${i+1}. ${p[0]}</h2><p>${p[1]}</p></section>`).join('')}<details><summary>Easy mistake to avoid</summary><p>${t.trap}</p></details><h2 style="margin-top:35px">Make it click</h2><div id="model-slot"></div><details><summary>Explain it back: can you teach the idea?</summary><p>Without looking above, explain: ${t.parts[0][0].toLowerCase()}. Include a cause, a mechanism, and an example.</p><label for="teach">Your explanation (stays on this page)</label><textarea id="teach" placeholder="It happens because…"></textarea><details><summary>Compare with a model explanation</summary><p>${t.parts[0][1]}</p></details></details><div class="actions">${button(progress.done.includes(id)?'✓ Explored':'Mark as explored',`complete('${id}')`)}<a class="btn light" href="#practice/${id}">Practice this section ↗</a><a class="btn light" href="#cards/${id}">Review flashcards</a></div><p class="mini">Models are simplified learning tools, not molecular-scale simulations.</p></article></div>`;renderModel(t.model)}
function complete(id){if(!progress.done.includes(id))progress.done.push(id);save();lesson(id)}
function lab(id='water'){main.innerHTML=`<span class="eyebrow">EXPLORE · PREDICT · EXPLAIN</span><h1 style="font-size:46px">The model lab.</h1><p>Make a prediction. Change one thing. Explain what happened.</p><label for="modelselect">Choose a model &nbsp;</label><select id="modelselect" onchange="location.hash='lab/'+this.value">${TOPICS.map(t=>`<option value="${t.model}" ${id===t.model?'selected':''}>${t.title}</option>`).join('')}</select><div id="model-slot"></div><p class="mini">All models are intentionally simplified. Sliders illustrate relationships; they are not calibrated experimental predictions.</p>`;renderModel(id)}
function renderModel(id){let s=$('#model-slot');if(!s)return;let body='';if(id==='water')body=`<h3>Why do water molecules attract?</h3><div class="controls"><label><input type="checkbox" id="bonds" checked onchange="updateWater()"> Show hydrogen bond</label><label><input type="checkbox" id="charges" checked onchange="updateWater()"> Show partial charges</label></div><svg id="water-svg" viewBox="0 0 600 260" role="img" aria-label="Two polar water molecules">${molecule(170,80)}${molecule(405,140)}<path id="hbond" d="M218 122L371 140" stroke="#b58e42" stroke-width="3" stroke-dasharray="6 7"/><text x="240" y="104" font-size="13">hydrogen bond</text></svg><div class="output">Solid connections inside each H₂O molecule: <b>polar covalent bonds</b>. Dashed attraction between molecules: <b>hydrogen bond</b>. Opposite partial charges attract.</div>`;
else if(id==='ph')body=`<h3>A tenfold scale</h3><label for="ph">Move the pH slider</label><input id="ph" type="range" min="0" max="14" value="7" style="width:100%;accent-color:#547947" oninput="updatePH()"><div style="height:15px;border-radius:10px;background:linear-gradient(90deg,#bd5b56,#e3ba59,#7fa86a,#64a6ab,#7967a8)"></div><div id="phout" class="output" aria-live="polite"></div><p>Predict: how much more H⁺ is present at pH 4 than pH 6?</p><details><summary>Check your prediction</summary>100 times as much: 10 × 10.</details>`;
else if(id==='building')body=`<h3>Build a chain. Then break it.</h3><p>Each circle is one monomer. The line is a covalent connection.</p><div class="controls">${button('Join a monomer','chain(1)')}${button('Hydrolyze one link','chain(-1)',true)}${button('Reset','chain(0)',true)}</div><div id="chainout" class="output" aria-live="polite"></div><svg id="chain-svg" viewBox="0 0 600 220" role="img" aria-label="Monomer chain"></svg>`;
else if(id==='families')body=`<h3>Molecule identity cards</h3><label for="family">Choose a family </label><select id="family" onchange="updateFamily()"><option>Carbohydrates</option><option>Lipids</option><option>Proteins</option><option>Nucleic acids</option></select><div id="familyout"></div>`;
else if(id==='protein')body=`<h3>One sequence. Several levels of structure.</h3><div class="tabs">${['Primary','Secondary','Tertiary','Quaternary','Denatured'].map((n,i)=>`<button onclick="protein(${i})" id="level${i}">${n}</button>`).join('')}</div><svg id="protein-svg" viewBox="0 0 600 220" role="img" aria-label="Protein structure diagram"></svg><div id="proteinout" class="output" aria-live="polite"></div>`;
else if(id==='enzyme')body=`<h3>Temperature and a hypothetical enzyme</h3><label for="temp">Temperature <input id="temp" type="range" min="0" max="80" value="35" oninput="enzyme()"></label><svg id="enzyme-svg" viewBox="0 0 600 230" role="img" aria-label="Illustrative enzyme activity curve"></svg><div class="output" id="enzymeout" aria-live="polite"></div>`;
else if(id==='osmosis')body=`<h3>Which way will water move?</h3><p>Assume the membrane lets water through but not the solute. Equal volumes initially; schematic, not to scale.</p><label for="outside">Outside solute concentration <input id="outside" type="range" min="0" max="100" value="70" oninput="osmosis()"></label><svg id="osmo-svg" viewBox="0 0 600 240" role="img" aria-label="Cell water movement model"></svg><div id="osmoout" class="output" aria-live="polite"></div>`;
else if(id==='energy')body=`<h3>Follow the carbon</h3><div class="controls">${button('Photosynthesis','energy(0)')}${button('Respiration','energy(1)',true)}</div><div id="energyout" class="output" aria-live="polite"></div><p>Predict: can a plant do both processes? Why would it need both?</p><details><summary>Reveal explanation</summary>Yes. Photosynthesis stores light energy in organic molecules. Respiration transfers energy from organic molecules to ATP for cellular work.</details>`;
else if(id==='feedback')body=`<h3>Body temperature feedback</h3><label for="bodytemp">Body temperature (°C) <input id="bodytemp" type="range" min="35" max="39" step="0.1" value="37" oninput="feedback()"></label><div id="feedbackout" class="output" aria-live="polite"></div><p>Illustrates the direction of regulation; not a medical tool or a complete physiological model.</p>`;
else if(id==='inheritance')body=`<h3>Build a simple genetic cross</h3><label>Parent 1 <select id="p1" onchange="inheritance()"><option>AA</option><option selected>Aa</option><option>aa</option></select></label> <label>Parent 2 <select id="p2" onchange="inheritance()"><option>AA</option><option selected>Aa</option><option>aa</option></select></label><div id="crossout" class="output" aria-live="polite"></div><p>Assumes one autosomal gene, two alleles, complete dominance, and equally likely gametes. Real inheritance can be more complex.</p>`;
else if(id==='selection')body=`<h3>Selection across generations</h3><label for="advantage">Relative reproductive advantage of inherited dark coloration <input id="advantage" type="range" min="-40" max="40" value="20" oninput="selection()"></label><label for="generation">Generations <input id="generation" type="range" min="0" max="15" value="5" oninput="selection()"></label><div id="selectionout" class="output" aria-live="polite"></div><p>Two-type mathematical illustration. Starts 50% dark, assumes inherited types, unlimited growth, and constant relative reproduction. No mutation, migration, or genetic drift.</p>`;
else if(id==='foodweb')body=`<h3>Energy available at trophic levels</h3><label for="producer">Producer energy (arbitrary units) <input id="producer" type="range" min="1000" max="20000" step="1000" value="10000" oninput="foodweb()"></label><div id="foodout" class="output" aria-live="polite"></div><p>Uses an illustrative 10% transfer per level. Actual transfer efficiency varies. Energy used in life processes ultimately disperses as heat.</p>`;
else{body='<p>Choose a model above.</p>'}s.innerHTML=`<section class="model">${body}</section>`;const init={ph:updatePH,building:()=>chain(0),families:updateFamily,protein:()=>protein(0),enzyme,osmosis,energy:()=>energy(0),feedback,inheritance,selection,foodweb};init[id]?.()}
function updateWater(){$('#hbond').style.display=$('#bonds').checked?'':'none';$('#water-svg').querySelectorAll('text').forEach(e=>{if(e.textContent.includes('δ'))e.style.display=$('#charges').checked?'':'none';if(e.textContent==='hydrogen bond')e.style.display=$('#bonds').checked?'':'none'})}
function updatePH(){let n=+$('#ph').value;$('#phout').innerHTML=`<strong>pH ${n} · ${n<7?'Acidic':n>7?'Basic':'Neutral at about 25°C'}</strong><br>H⁺ concentration: approximately 10<sup>−${n}</sup> mol/L.<br>${n<7?`${(10**(7-n)).toLocaleString()}× more H⁺ than pH 7.`:n>7?`${(10**(n-7)).toLocaleString()}× less H⁺ than pH 7.`:'This is our comparison point.'}`}
let links=0;function chain(d){if(d===0)links=0;else links=Math.max(0,Math.min(7,links+d));$('#chainout').innerHTML=`<b>${links+1} monomer${links?'s':''} · ${links} link${links===1?'':'s'}</b><br>${d>0?'Joining one monomer releases one H₂O.':d<0&&links<7?'Breaking one link uses one H₂O.':'Start with one monomer. Add up to seven more.'} Assembling this whole chain from separate monomers releases ${links} water molecule${links===1?'':'s'} in this simplified model.`;$('#chain-svg').innerHTML=Array.from({length:links+1},(_,i)=>`${i?`<line x1="${40+(i-1)*72}" y1="100" x2="${40+i*72}" y2="100" stroke="#6b8851" stroke-width="7"/>`:''}<circle cx="${40+i*72}" cy="100" r="25" fill="${i%2?'#d5e79d':'#4a785a'}"/><text x="${40+i*72}" y="106" text-anchor="middle" fill="${i%2?'#173a34':'white'}">${i+1}</text>`).join('')}
function updateFamily(){let n=$('#family').selectedIndex;const rows=[['Monosaccharides → polysaccharides','Quick fuel, energy storage, plant cell-wall support','Glucose, starch, glycogen, cellulose','C, H, O; many have an approximate 1:2:1 ratio'],['Glycerol + fatty acids in triglycerides; not repeating polymers','Energy storage, insulation, membranes, some hormones','Fats, oils, phospholipids, steroids','Mostly C, H, O; phospholipids also contain P'],['Amino acids → polypeptides','Catalysis, transport, signaling, structure','Amylase, hemoglobin, collagen','C, H, O, N; some also S'],['Nucleotides → DNA or RNA','Store and help express genetic information','DNA, RNA','C, H, O, N, P']][n];$('#familyout').innerHTML=`<div class="tablewrap"><table><tbody>${['Building blocks','Jobs','Examples','Elements'].map((a,i)=>`<tr><th>${a}</th><td>${rows[i]}</td></tr>`).join('')}</tbody></table></div><div class="output">Ask yourself: how does this family’s structure support one of its jobs?</div>`}
function protein(n){document.querySelectorAll('[id^=level]').forEach((e,i)=>e.classList.toggle('active',i===n));let pts=Array.from({length:28},(_,i)=>{let x=35+i*19,y=110;if(n===1)y+=Math.sin(i*.8)*42;if(n===2){x=300+Math.cos(i*.65)*(55+i*2);y=110+Math.sin(i*.65)*70}if(n===3){x=170+Math.cos(i*.65)*85;y=110+Math.sin(i*.65)*65}if(n===4)y+=Math.sin(i*.4)*20;return [x,y]});let path=pts.map(p=>p.join(',')).join(' ');$('#protein-svg').innerHTML=`<polyline points="${path}" stroke="#49775c" stroke-width="8" fill="none"/>${n===3?`<polyline points="${pts.map(([x,y])=>[x+245,y].join(',')).join(' ')}" stroke="#b9cd7b" stroke-width="8" fill="none"/>`:''}${pts.filter((_,i)=>i%2===0).map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="8" fill="${i%2?'#c6d78d':'#3b654c'}"/>`).join('')}<text x="300" y="215" text-anchor="middle" font-size="13">Schematic: each chain keeps the same sequence</text>`;$('#proteinout').innerHTML=['<b>Primary:</b> amino acid order held by peptide bonds. A sequence is not the same thing as a folded shape.','<b>Secondary:</b> local helices and sheets stabilized by hydrogen bonds between backbone groups. The curve illustrates a local pattern, not atomic geometry.','<b>Tertiary:</b> the overall fold of one chain, stabilized by side-chain interactions and its environment.','<b>Quaternary:</b> two or more folded polypeptide subunits working together. Colors represent different subunits.','<b>Denatured:</b> the useful fold is disrupted. The peptide backbone usually remains intact, so the sequence has not necessarily changed.'][n]}
function enzyme(){let t=+$('#temp').value;const rate=x=>x<=37?100*Math.exp(-(((x-37)/25)**2)):100*Math.exp(-(((x-37)/12)**2));let pts=Array.from({length:81},(_,x)=>`${50+x*6},${185-rate(x)*1.4}`).join(' ');$('#enzyme-svg').innerHTML=`<path d="M50 25V185H550" fill="none" stroke="#afbeaa"/><polyline points="${pts}" fill="none" stroke="#427653" stroke-width="4"/><circle cx="${50+t*6}" cy="${185-rate(t)*1.4}" r="7" fill="#be8742"/><text x="250" y="220">Temperature (0–80°C)</text><text x="55" y="20">Relative activity</text>`;$('#enzymeout').innerHTML=`<b>${t}°C · illustrative activity ${Math.round(rate(t))}%</b><br>${t<25?'Cooler conditions slow molecular movement and encounters.':t<=42?'This hypothetical enzyme has a peak near 37°C. Other enzymes have different optima.':'At higher temperatures, disrupted folding reduces activity in this model.'}`}
function osmosis(){let o=+$('#outside').value,inside=50;$('#osmo-svg').innerHTML=`<rect x="20" y="20" width="560" height="200" rx="15" fill="#edf3e4"/><circle cx="300" cy="120" r="75" fill="#d0e2b3" stroke="#52784d" stroke-width="4"/><text x="300" y="110" text-anchor="middle">Inside: 50 units</text><text x="50" y="50">Outside: ${o} units</text><text x="300" y="155" font-size="35" text-anchor="middle">${o>inside?'H₂O →':o<inside?'← H₂O':'⇄ H₂O'}</text>`;$('#osmoout').innerHTML=o>inside?'Outside is hypertonic. Net water movement is out; an animal cell tends to shrink.':o<inside?'Outside is hypotonic. Net water movement is in; an animal cell tends to swell.':'Solutions are isotonic in this model. Water moves both ways with no net movement.'}
function energy(n){$('#energyout').innerHTML=n?'<h3>Glucose + O₂ → CO₂ + H₂O</h3>Cellular respiration transfers energy from organic molecules to ATP; some energy disperses as heat. Follow carbon: glucose carbon becomes CO₂ carbon.':'<h3>CO₂ + H₂O + light → sugar + O₂</h3>Photosynthesis stores light energy in organic molecules. Follow carbon: CO₂ carbon becomes sugar carbon. This is a simplified overall relationship, not a one-step reaction.'}
function feedback(){let t=+$('#bodytemp').value;$('#feedbackout').innerHTML=`<h3>${t.toFixed(1)}°C</h3>${t>37.2?'Temperature rises → sensing/control → sweating and increased skin blood flow → greater heat loss → temperature moves downward.':t<36.8?'Temperature falls → sensing/control → shivering and reduced skin blood flow → more heat production/conservation → temperature moves upward.':'Near the illustrative set point: heat production and heat loss are approximately balanced.'}<p>Negative feedback opposes a deviation; it does not eliminate all variation.</p>`}
function inheritance(){let a=$('#p1').value.split(''),b=$('#p2').value.split(''),g=a.flatMap(x=>b.map(y=>[x,y].sort().join(''))),count=v=>g.filter(x=>x===v).length*25;$('#crossout').innerHTML=`<table><tr><th>Gametes</th>${b.map(x=>`<th>${x}</th>`).join('')}</tr>${a.map(x=>`<tr><th>${x}</th>${b.map(y=>`<td>${[x,y].sort().join('')}</td>`).join('')}</tr>`).join('')}</table><p>AA: ${count('AA')}% · Aa: ${count('Aa')}% · aa: ${count('aa')}%<br>Dominant phenotype: ${100-count('aa')}% · recessive phenotype: ${count('aa')}%. Each offspring is a new independent event.</p>`}
function selection(){let a=+$('#advantage').value/100,n=+$('#generation').value,d=(1+a)**n,p=100*d/(1+d);$('#selectionout').innerHTML=`<b>After ${n} generations, dark type: ${p.toFixed(1)}%</b><div style="height:25px;background:#dce7bd;margin:20px 0"><div style="height:100%;width:${p}%;background:#3c634c"></div></div>Relative reproductive difference: ${Math.round(a*100)}%. ${a>0?'Dark type becomes more frequent.':a<0?'Dark type becomes less frequent.':'No frequency change in this model.'} Selection changes the composition of the population, not the color of an individual.`}
function foodweb(){let n=+$('#producer').value;$('#foodout').innerHTML=['Producers','Primary consumers','Secondary consumers','Tertiary consumers'].map((s,i)=>`<p><b>${s}: ${n/10**i} units</b><span style="display:block;height:20px;width:${100/2**i}%;background:${i%2?'#9db471':'#4a7355'}"></span></p>`).join('')}
function cards(filter='unit2'){main.innerHTML=`<div class="center"><span class="eyebrow">RECALL, DON’T JUST REREAD</span><h1 style="font-size:44px">Make it stick.</h1><p>Try answering out loud before flipping. “Still learning” keeps a card in your review pile.</p><label for="cardfilter">Topic </label><select id="cardfilter" onchange="startDeck()">${options()}</select><label style="margin-left:15px"><input type="checkbox" id="unknown" onchange="startDeck()"> Still learning only</label><div id="flasharea"></div></div>`;$('#cardfilter').value=filter;startDeck()}
function startDeck(){deck=shuffle(CARDS.map((c,i)=>({...c,id:i})).filter(c=>matches(c.topic,$('#cardfilter').value)&&(!$('#unknown').checked||!progress.known.includes(c.id))));ci=0;flipped=false;showCard()}
function showCard(){let c=deck[ci];if(!c){$('#flasharea').innerHTML='<div class="empty">No cards in this review pile. Choose another topic or turn off “Still learning only.”</div>';return}$('#flasharea').innerHTML=`<div class="quiztop"><span>${topic(c.topic).title}</span><span>Card ${ci+1} / ${deck.length} · ${progress.known.length} known overall</span></div><button class="flash ${flipped?'answer':''}" onclick="flip()" aria-label="${flipped?'Show prompt':'Reveal answer'}"><small>${flipped?'THE EXPLANATION':'THINK FIRST · CLICK TO FLIP'}</small>${flipped?c.back:c.front}</button><div class="actions">${button('← Previous','cardMove(-1)',true)}${button(flipped?'Show prompt':'Reveal answer','flip()',true)}${button('Next →','cardMove(1)',true)}</div>${flipped?`<div class="actions">${button('Still learning','know(false)',true)}${button('Got it ✓','know(true)')}</div>`:''}<p class="mini">Progress is stored in this browser only. Flashcards can be flipped with Enter or Space when focused.</p>`}
function flip(){flipped=!flipped;showCard()}function cardMove(d){ci=(ci+d+deck.length)%deck.length;flipped=false;showCard()}function know(v){let id=deck[ci].id;progress.known=progress.known.filter(x=>x!==id);if(v)progress.known.push(id);save();cardMove(1)}
function practice(filter='unit2'){main.innerHTML=`<div class="center"><span class="eyebrow">PUT THE IDEAS TO WORK</span><h1 style="font-size:44px">Practice with a purpose.</h1><p>Original Regents-style practice, with explanations. These are study questions, not official exam items.</p><div class="model"><label for="qfilter">Choose a topic </label><select id="qfilter">${options()}</select><div class="tabs"><button id="studyMode" class="active" onclick="setMode('study')">Learn as you go</button><button id="testMode" onclick="setMode('test')">Practice test</button></div><p id="modedesc">Get an explanation after each answer.</p><div class="actions">${button('Start 10 questions','startQuiz(false)')}${button('Review missed questions','startQuiz(true)',true)}</div><p class="mini">Questions are shuffled. Shorter topic sets include every available question in that topic.</p></div><div id="quizarea"></div></div>`;$('#qfilter').value=filter;mode='study'}
function setMode(m){mode=m;$('#studyMode').classList.toggle('active',m==='study');$('#testMode').classList.toggle('active',m==='test');$('#modedesc').textContent=m==='study'?'Get an explanation after each answer.':'Answer the full set before viewing your score and explanations.'}
function startQuiz(missed){quiz=shuffle(QUESTIONS.map((q,i)=>({...q,id:i})).filter(q=>matches(q.topic,$('#qfilter').value)&&(!missed||progress.missed.includes(q.id)))).slice(0,10);qi=0;answers=[];checked=false;showQuestion()}
function showQuestion(){let q=quiz[qi];if(!q){$('#quizarea').innerHTML='<div class="empty">No missed questions in this topic yet. Try a new practice set.</div>';return}$('#quizarea').innerHTML=`<div class="quiztop"><span>${topic(q.topic).title}</span><span>Question ${qi+1} / ${quiz.length}</span></div><div class="bar"><i style="width:${qi/quiz.length*100}%"></i></div><h2 style="margin:25px 0">${q.prompt}</h2>${q.options.map((o,i)=>`<button class="option ${answers[qi]===i?'selected':''}" onclick="choose(${i})" ${checked?'disabled':''}>${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<div id="qfeedback" aria-live="polite"></div><div class="actions">${button(mode==='study'?'Check answer':'Save & next','checkAnswer()')}<span id="qhint" role="status"></span></div>`}
function choose(i){answers[qi]=i;document.querySelectorAll('.option').forEach((e,j)=>e.classList.toggle('selected',i===j));$('#qhint').textContent=''}
function checkAnswer(){if(answers[qi]===undefined){$('#qhint').textContent='Choose an answer first.';return}if(mode==='test'){nextQ();return}if(checked){nextQ();return}checked=true;let q=quiz[qi];document.querySelectorAll('.option').forEach((e,i)=>{e.disabled=true;e.classList.toggle('correct',i===q.answer);e.classList.toggle('wrong',i===answers[qi]&&i!==q.answer)});$('#qfeedback').innerHTML=`<div class="feedback"><strong>${answers[qi]===q.answer?'That’s right.':'Let’s untangle that.'}</strong><p>${q.why}</p></div>`;$('#qfeedback').nextElementSibling.querySelector('button').textContent=qi===quiz.length-1?'See results':'Next question →'}
function nextQ(){qi++;checked=false;if(qi===quiz.length)results();else showQuestion()}
function results(){let correct=0;quiz.forEach((q,i)=>{progress.missed=progress.missed.filter(n=>n!==q.id);if(answers[i]===q.answer)correct++;else progress.missed.push(q.id)});save();$('#quizarea').innerHTML=`<div class="callout"><h2>${correct} / ${quiz.length} · ${Math.round(correct/quiz.length*100)}%</h2><p>${correct===quiz.length?'You connected the ideas. Try explaining one to a friend.':'Missed questions are now in your review pile. Use the explanations to find the missing connection.'}</p></div>${quiz.map((q,i)=>`<details ${answers[i]!==q.answer?'open':''}><summary>${answers[i]===q.answer?'✓':'↻'} ${q.prompt}</summary><p>Your answer: ${q.options[answers[i]]}<br><b>Correct: ${q.options[q.answer]}</b></p><p>${q.why}</p><a href="#lesson/${q.topic}">Review the lesson ↗</a></details>`).join('')}<div class="actions">${button('Try a new set','startQuiz(false)')}${button('Review missed','startQuiz(true)',true)}</div>`}
function sources(){main.innerHTML=`<div class="center"><span class="eyebrow">ABOUT THIS GUIDE</span><h1 style="font-size:40px">Built for understanding.</h1><p>Unit 2 topics were selected from the uploaded notes video: properties of water, pH, indicators, biological molecules, synthesis and hydrolysis, and protein structure. Enzymes are included as a clearly labeled extension. Later sections are organized by subject because classroom unit numbering varies.</p><p>Lessons, diagrams, questions, and explanations are original. This site does not publish the notes video or reproduce worksheet pages. It is an independent study aid, not a complete course or official NYSED product.</p><h2>Check the science</h2><p><a href="https://www.nysed.gov/state-assessment/life-science-biology">NYSED: Life Science Biology assessment resources ↗</a><br><a href="https://openstax.org/books/biology-2e/pages/2-2-water">OpenStax Biology 2e: water ↗</a><br><a href="https://openstax.org/books/biology-2e/pages/3-1-synthesis-of-biological-macromolecules">OpenStax: biological macromolecules ↗</a><br><a href="https://openstax.org/books/biology-2e/pages/3-4-proteins">OpenStax: proteins ↗</a><br><a href="https://openstax.org/books/biology-2e/pages/1-introduction">OpenStax Biology 2e: broader reference ↗</a></p><h2>Your progress</h2><p>Completion, known cards, and missed questions are saved locally in this browser. There are no accounts, shared class scores, or server-stored student records. Clearing browser data removes progress.</p><details><summary>Reset my study progress</summary><p>This clears local completion, flashcard, and question history.</p>${button('Reset progress in this browser','resetProgress()',true)}</details><p class="mini">Updated October 2026. External font requests may be made to Google Fonts; system fonts work if unavailable.</p></div>`}
function resetProgress(){progress={done:[],known:[],missed:[]};save();sources()}
function route(){let [page,id]=(location.hash.slice(1)||'home').split('/');if(page==='lesson')lesson(id);else if(page==='lab')lab(id||'water');else if(page==='cards')cards(id||'unit2');else if(page==='practice')practice(id||'unit2');else if(page==='sources')sources();else home();window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();
